 public static function create(PDO $db,array $actor,array $in,int $quoteId=0):string {
 MemberServices::requireMember($db,$actor);$settings=StoreSettings::get($db);if(!$settings['enable_sales']||trim($settings['sales_terms'])==='')throw new HttpError(422,'فروشگاه تا تکمیل و فعال‌سازی شرایط فروش، سفارش جدید نمی‌پذیرد.');$gateway=self::gateway();$cart=StoreCart::token($db,$actor);$key=Security::text($in,'checkout_key',64);if(!preg_match('/^[a-f0-9]{64}$/D',$key)||!hash_equals($_SESSION['checkout_key']??'',$key))throw new HttpError(422,'شناسه تسویه معتبر نیست.');
 try{return Db::transaction($db,function()use($db,$actor,$in,$quoteId,$settings,$gateway,$cart,$key){
 Db::query($db,'SELECT token FROM carts WHERE token=?'.StoreAccess::lock($db),[$cart])->fetch();$existing=Db::query($db,'SELECT o.id,o.token,d.payload FROM orders o JOIN store_order_details d ON d.order_id=o.id WHERE o.checkout_key=? AND d.user_id=?',[$key,$actor['id']])->fetch();if($existing){if((int)(Protocol::decode($existing['payload'])['quote_id']??0)!==$quoteId)throw new HttpError(409,'شناسه تسویه متعلق به درخواست دیگری است.');return $existing['token'];}
 $quote=null;$rows=StoreCart::items($db,$actor);
 if($quoteId){$quote=Db::query($db,'SELECT * FROM store_quotes WHERE id=? AND user_id=?'.StoreAccess::lock($db),[$quoteId,$actor['id']])->fetch();if(!$quote)throw new HttpError(404,'استعلام پیدا نشد.');if($quote['order_id'])return (string)Db::query($db,'SELECT token FROM orders WHERE id=?',[$quote['order_id']])->fetchColumn();if($quote['status']!=='offered'||$quote['expires_at']<time()||$quote['amount']===null)throw new HttpError(422,'پیشنهاد قیمت معتبر نیست.');[$p,$v]=StoreCart::product($db,(int)$quote['variant_id']);$rows=[['id'=>0,'variant_id'=>$v['id'],'quantity'=>$quote['quantity'],'product'=>$p,'variant'=>$v,'data'=>Protocol::decode($quote['payload']),'quoted_price'=>$quote['amount'],'price'=>(int)$quote['amount'],'error'=>'']];}
 if(!$rows)throw new HttpError(422,'سبد خالی است.');$subtotal=0;$physical=false;$grams=0;
 foreach($rows as &$r){if($r['error'])throw new HttpError(422,$r['error']);$p=$r['product'];$v=$r['variant'];if((int)$r['quoted_price']!==(int)$r['price']&&empty($in['accept_price_changes']))throw new HttpError(409,'قیمت محصول تغییر کرده است؛ قیمت جدید را بررسی و تأیید کنید.');$subtotal=StoreAccess::money($subtotal+$r['price']*$r['quantity']);if($p['delivery']!=='digital'){$physical=true;$grams+=(int)($p['meta']['weight_grams']??0)*(int)$r['quantity'];}
 if($p['delivery']!=='physical'&&$p['production']==='ready'&&($p['meta']['digital_files']??null)===[])throw new HttpError(422,'فایل‌های محصول برای فروش جدید انتخاب نشده‌اند.');if($p['delivery']!=='physical'&&$p['production']==='ready'&&!Db::query($db,"SELECT id FROM store_files WHERE product_id=? AND kind='catalog' AND active=1",[$p['id']])->fetchColumn())throw new HttpError(422,'فایل دیجیتال محصول آماده نشده است.');
 if(!$v['unlimited'])self::stock($db,(int)$v['id'],-(int)$r['quantity'],$actor,'رزرو سفارش');$r['materials']=StoreOperationsSchema::ready($db)?Db::query($db,'SELECT variant_id,units FROM store_material_links WHERE product_id=? ORDER BY variant_id',[$p['id']])->fetchAll():[];foreach($r['materials'] as $material)self::stock($db,(int)$material['variant_id'],-((int)$material['units']*(int)$r['quantity']),$actor,'رزرو ماده اولیه');
