 $address=['customer'=>Security::text($in,'customer',150),'phone'=>Security::phone(Security::text($in,'phone',20)),'address'=>'','postal_code'=>'','province'=>'','city'=>''];
 if($physical){if(!empty($in['address_id'])){$saved=Db::query($db,'SELECT * FROM account_addresses WHERE id=? AND user_id=?',[(int)$in['address_id'],$actor['id']])->fetch();if(!$saved)throw new HttpError(422,'نشانی متعلق به شما نیست.');$address=array_replace($address,['customer'=>$saved['recipient'],'phone'=>$saved['phone'],'address'=>$saved['address'],'postal_code'=>$saved['postal_code']]);}else{$address['address']=Security::text($in,'address',2000);$address['postal_code']=Security::normalize(Security::text($in,'postal_code',10));}$address['province']=Security::text($in,'province',150);$address['city']=Security::text($in,'city',150);if(!preg_match('/^\d{10}$/D',$address['postal_code']))throw new HttpError(422,'کدپستی ۱۰ رقمی وارد کنید.');}
 $shipping=$physical?StoreSettings::shipping($settings,Security::text($in,'shipping_method',40),$address,$subtotal,$grams):0;$code=Security::text($in,'discount_code',80,false);$discount=$code!==''?self::coupon($db,$actor,$code,$rows,$subtotal):0;$tax=(int)round(($subtotal-$discount)*$settings['tax_bps']/10000);$total=StoreAccess::money($subtotal-$discount+$shipping+$tax);$token=bin2hex(random_bytes(32));
 $order=Db::insert($db,'orders',['token'=>$token,'checkout_key'=>$key,'cart_token'=>$cart,'customer'=>$address['customer'],'phone'=>$address['phone'],'address'=>$address['address'],'postal_code'=>$address['postal_code'],'subtotal'=>$subtotal,'discount'=>$discount,'shipping'=>$shipping,'total'=>$total,'discount_code'=>$code?:null,'status'=>'pending','created_at'=>date('Y-m-d H:i:s')]);
 Db::insert($db,'account_order_owners',['order_id'=>$order,'user_id'=>$actor['id'],'linked_at'=>date(DATE_ATOM)]);
 Db::insert($db,'store_order_details',['order_id'=>$order,'user_id'=>$actor['id'],'currency'=>'TOMAN','tax'=>$tax,'payload'=>Protocol::encode(['address'=>$address,'shipping_method'=>$physical?$in['shipping_method']:null,'settings'=>array_intersect_key($settings,array_flip(['sales_terms','cancellation','privacy','shipping_policy'])),'quote_id'=>$quoteId]),'expires_at'=>time()+$settings['reservation_minutes']*60,'reservation_state'=>'reserved','created_at'=>date(DATE_ATOM)]);
 foreach($rows as $r){$p=$r['product'];$v=$r['variant'];$iid=Db::insert($db,'order_items',['order_id'=>$order,'variant_id'=>$v['id'],'title'=>$p['title'],'attributes'=>$v['attributes'],'price'=>$r['price'],'quantity'=>$r['quantity']]);$snapshot=['revision_limit'=>(int)($p['meta']['revision_limit']??0),'materials'=>$r['materials']??[],'product_id'=>$p['id'],'sku'=>$v['sku'],'base_price'=>(int)($v['sale_price']??$v['price']),'currency'=>'TOMAN','form'=>$r['data'],'unlimited'=>(bool)$v['unlimited'],'digital_rights'=>$p['meta']['digital_rights']??$settings['digital_rights'],'sales_terms'=>$p['meta']['sales_terms']??$settings['sales_terms'],'digital_files'=>$p['meta']['digital_files']??array_map('intval',Db::query($db,"SELECT id FROM store_files WHERE product_id=? AND kind='catalog' AND active=1 ORDER BY id",[$p['id']])->fetchAll(PDO::FETCH_COLUMN)),'download_limit'=>$settings['download_limit'],'download_days'=>$settings['download_days'],'created_at'=>date(DATE_ATOM)];
 Db::insert($db,'store_item_details',['item_id'=>$iid,'product_id'=>$p['id'],'delivery'=>$p['delivery'],'production'=>$p['production'],'snapshot'=>Protocol::encode($snapshot),'status'=>'new','approval_required'=>!empty($p['meta']['customer_approval'])&&$p['production']==='custom'?1:0,'digital_state'=>'pending','updated_at'=>date(DATE_ATOM)]);
 foreach($r['data']['files']??[] as $fid){$changed=Db::query($db,'UPDATE store_files SET item_id=?,owner_id=? WHERE id=? AND cart_token=? AND item_id IS NULL',[$iid,$actor['id'],$fid,$cart])->rowCount();if(!$changed)throw new HttpError(409,'پیوست قبلاً به سفارش دیگری متصل شده است.');}
 }
 if($code!=='')Db::insert($db,'store_coupon_redemptions',['code'=>$code,'user_id'=>$actor['id'],'order_id'=>$order,'amount'=>$discount,'state'=>'reserved']);
 $ref=bin2hex(random_bytes(24));Db::insert($db,'payments',['order_id'=>$order,'driver'=>$gateway->name(),'reference'=>$ref,'status'=>'pending','amount'=>$total]);Db::insert($db,'store_payment_attempts',['order_id'=>$order,'reference'=>$ref,'driver'=>$gateway->name(),'amount'=>$total,'status'=>'pending','created_at'=>date(DATE_ATOM)]);Db::insert($db,'order_history',['order_id'=>$order,'status'=>'pending','created_at'=>date(DATE_ATOM)]);
 if($quote)Db::query($db,"UPDATE store_quotes SET order_id=?,status='accepted' WHERE id=?",[$order,$quoteId]);else Db::query($db,'DELETE FROM store_cart_lines WHERE cart_token=?',[$cart]);
 StoreOps::notify($db,$actor['id'],$order,'order-'.$order,'سفارش شما ثبت شد.');StoreAccess::audit($db,$actor,'checkout','order',$order,[],['total'=>$total,'currency'=>'TOMAN']);return $token;
 });}catch(\PDOException $e){if(str_contains(strtolower($e->getMessage()),'locked')||in_array((int)($e->errorInfo[1]??0),[1205,1213],true))throw new HttpError(409,'خرید هم‌زمان انجام شد؛ موجودی را دوباره بررسی کنید.');throw $e;}
 }
 public static function stock(PDO $db,int $variant,int $delta,array $actor,string $reason):void {
 $v=Db::query($db,'SELECT stock FROM variants WHERE id=?'.StoreAccess::lock($db),[$variant])->fetch();if(!$v||((int)$v['stock']+$delta)<0)throw new HttpError(409,'موجودی کالا تغییر کرده است.');if(!Db::query($db,'UPDATE variants SET stock=stock+? WHERE id=? AND stock+?>=0',[$delta,$variant,$delta])->rowCount())throw new HttpError(409,'موجودی کافی نیست.');Db::insert($db,'store_inventory_movements',['variant_id'=>$variant,'delta'=>$delta,'before_stock'=>$v['stock'],'after_stock'=>$v['stock']+$delta,'reason'=>$reason,'user_id'=>$actor['id'],'created_at'=>date(DATE_ATOM)]);
 }
 public static function coupon(PDO $db,array $actor,string $code,array $rows,int $subtotal):int {
 $d=Db::query($db,'SELECT * FROM discounts WHERE code=?'.StoreAccess::lock($db),[$code])->fetch();if(!$d||strtotime($d['expires'])<time()||$subtotal<(int)$d['min_total'])throw new HttpError(422,'کد تخفیف معتبر نیست.');$rules=Db::query($db,'SELECT payload FROM store_coupon_rules WHERE code=?',[$code])->fetchColumn();$r=$rules?Protocol::decode($rules):[];if(($r['starts']??0)>time()||(!empty($r['users'])&&!in_array((int)$actor['id'],array_map('intval',$r['users']),true)))throw new HttpError(422,'این تخفیف برای این حساب معتبر نیست.');if(($r['per_user']??0)>0&&(int)Db::query($db,"SELECT COUNT(*) FROM store_coupon_redemptions WHERE code=? AND user_id=? AND state<>'released'",[$code,$actor['id']])->fetchColumn()>=$r['per_user'])throw new HttpError(422,'سقف استفاده شما از تخفیف تکمیل شده است.');
 $eligible=0;foreach($rows as $row){$pid=(int)$row['product']['id'];if(!empty($r['products'])&&!in_array($pid,array_map('intval',$r['products']),true))continue;if(!empty($r['categories'])&&!array_intersect(array_map('intval',$r['categories']),array_map('intval',array_column($row['product']['categories'],'id'))))continue;if(empty($r['combine_sale'])&&isset($row['variant'])&&$row['variant']['sale_price']!==null)continue;$eligible+=$row['price']*$row['quantity'];}if(!$eligible)throw new HttpError(422,'کالاهای سبد مشمول این تخفیف نیستند.');if(!Db::query($db,'UPDATE discounts SET uses=uses+1 WHERE code=? AND uses<max_uses',[$code])->rowCount())throw new HttpError(422,'ظرفیت تخفیف تکمیل شده است.');return min($eligible,(int)floor($eligible*(int)$d['percent']/100),isset($r['max_discount'])&&$r['max_discount']>0?(int)$r['max_discount']:2000000000);
 }
 public static function release(PDO $db,array $order,array $actor):void {
 if(!Db::query($db,"UPDATE store_order_details SET reservation_state='released' WHERE order_id=? AND reservation_state='reserved'",[$order['id']])->rowCount())return;
 foreach(Db::query($db,'SELECT i.*,d.snapshot FROM order_items i JOIN store_item_details d ON d.item_id=i.id WHERE i.order_id=? ORDER BY i.variant_id,i.id',[$order['id']])->fetchAll() as $i){$snap=Protocol::decode($i['snapshot']);if(empty($snap['unlimited']))self::stock($db,(int)$i['variant_id'],(int)$i['quantity'],$actor,'آزادسازی رزرو سفارش #'.$order['id']);foreach($snap['materials']??[] as $material)self::stock($db,(int)$material['variant_id'],(int)$material['units']*(int)$i['quantity'],$actor,'آزادسازی رزرو ماده اولیه');}
 if($order['discount_code']&&Db::query($db,"UPDATE store_coupon_redemptions SET state='released' WHERE order_id=? AND state='reserved'",[$order['id']])->rowCount())Db::query($db,'UPDATE discounts SET uses=uses-1 WHERE code=? AND uses>0',[$order['discount_code']]);
 }
 public static function pay(PDO $db,array $actor,string $token,array $in):void {
 $gateway=self::gateway();Db::transaction($db,function()use($db,$actor,$token,$in,$gateway){$o=Db::query($db,'SELECT * FROM orders WHERE token=?'.StoreAccess::lock($db),[$token])->fetch();if(!$o||!StoreAccess::owner($db,(int)$o['id'],$actor))throw new HttpError(404,'سفارش پیدا نشد.');$attempt=Db::query($db,'SELECT * FROM store_payment_attempts WHERE order_id=? AND reference=?',[$o['id'],Security::text($in,'reference',100)])->fetch();if(!$attempt)throw new HttpError(422,'تلاش پرداخت معتبر نیست.');if($attempt['status']!=='pending')return;if($o['status']!=='pending'||(int)$attempt['amount']!==(int)$o['total'])throw new HttpError(422,'سفارش قابل پرداخت نیست.');$detail=Db::query($db,'SELECT * FROM store_order_details WHERE order_id=?',[$o['id']])->fetch();if($detail['expires_at']<time())throw new HttpError(409,'رزرو منقضی شده؛ پرداخت مجدد را انتخاب کنید.');$success=$gateway->verify($attempt,$in);$state=$success?'verified':'failed';Db::query($db,'UPDATE store_payment_attempts SET status=?,verified_at=? WHERE id=?',[$state,date(DATE_ATOM),$attempt['id']]);Db::query($db,'UPDATE payments SET status=? WHERE order_id=? AND reference=?',[$state,$o['id'],$attempt['reference']]);Db::query($db,'UPDATE orders SET status=? WHERE id=?',[$success?'paid':'payment_failed',$o['id']]);
 if($success){Db::query($db,"UPDATE store_order_details SET reservation_state='consumed' WHERE order_id=?",[$o['id']]);Db::query($db,"UPDATE store_coupon_redemptions SET state='consumed' WHERE order_id=?",[$o['id']]);foreach(Db::query($db,'SELECT d.* FROM store_item_details d JOIN order_items i ON i.id=d.item_id WHERE i.order_id=?',[$o['id']])->fetchAll() as $i)if($i['production']==='ready'&&$i['delivery']!=='physical')Db::query($db,"UPDATE store_item_details SET digital_state='available',status=?,download_until=? WHERE item_id=?",[$i['delivery']==='digital'?'completed':'ready',(Protocol::decode($i['snapshot'])['download_days']??0)?time()+Protocol::decode($i['snapshot'])['download_days']*86400:0,$i['item_id']]);}else self::release($db,$o,$actor);
 Db::insert($db,'order_history',['order_id'=>$o['id'],'status'=>$success?'paid':'payment_failed','created_at'=>date(DATE_ATOM)]);StoreOps::notify($db,$actor['id'],(int)$o['id'],'payment-'.$attempt['id'],$success?'پرداخت آزمایشی تأیید شد.':'پرداخت ناموفق بود؛ امکان تلاش مجدد دارید.');StoreAccess::audit($db,$actor,'payment.'.$state,'order',(int)$o['id'],[],['attempt'=>$attempt['id'],'amount'=>$attempt['amount']]);});
 }
 public static function retry(PDO $db,array $actor,int $id):void {
 $gateway=self::gateway();Db::transaction($db,function()use($db,$actor,$id,$gateway){$o=Db::query($db,'SELECT * FROM orders WHERE id=?'.StoreAccess::lock($db),[$id])->fetch();if(!$o||!StoreAccess::owner($db,$id,$actor))throw new HttpError(404,'سفارش پیدا نشد.');$d=Db::query($db,'SELECT * FROM store_order_details WHERE order_id=?',[$id])->fetch();if(!in_array($o['status'],['pending','payment_failed','expired'],true))throw new HttpError(422,'پرداخت مجدد برای این سفارش مجاز نیست.');if($o['status']==='pending'&&$d['expires_at']>time())return;if($d['reservation_state']==='reserved')self::release($db,$o,$actor);
 $rows=[];foreach(Db::query($db,'SELECT i.*,s.snapshot FROM order_items i JOIN store_item_details s ON s.item_id=i.id WHERE i.order_id=? ORDER BY i.variant_id,i.id',[$id])->fetchAll() as $i){[$p,$v]=StoreCart::product($db,(int)$i['variant_id']);$snap=Protocol::decode($i['snapshot']);if((int)($v['sale_price']??$v['price'])!==(int)$snap['base_price'])throw new HttpError(409,'قیمت کالا تغییر کرده؛ سفارش تازه با قیمت فعلی لازم است.');if(empty($snap['unlimited']))self::stock($db,(int)$i['variant_id'],-(int)$i['quantity'],$actor,'رزرو پرداخت مجدد');foreach($snap['materials']??[] as $material)self::stock($db,(int)$material['variant_id'],-((int)$material['units']*(int)$i['quantity']),$actor,'رزرو مجدد ماده اولیه');$rows[]=['product'=>$p,'variant'=>$v,'price'=>(int)$i['price'],'quantity'=>(int)$i['quantity']];}
 if($o['discount_code']){self::coupon($db,$actor,$o['discount_code'],$rows,(int)$o['subtotal']);Db::query($db,"UPDATE store_coupon_redemptions SET state='reserved' WHERE order_id=?",[$id]);}$ref=bin2hex(random_bytes(24));Db::query($db,"UPDATE store_payment_attempts SET status='expired' WHERE order_id=? AND status='pending'",[$id]);Db::insert($db,'store_payment_attempts',['order_id'=>$id,'reference'=>$ref,'driver'=>$gateway->name(),'amount'=>$o['total'],'status'=>'pending','created_at'=>date(DATE_ATOM)]);Db::query($db,"UPDATE payments SET reference=?,status='pending' WHERE order_id=?",[$ref,$id]);Db::query($db,"UPDATE orders SET status='pending' WHERE id=?",[$id]);Db::query($db,"UPDATE store_order_details SET reservation_state='reserved',expires_at=? WHERE order_id=?",[time()+StoreSettings::get($db)['reservation_minutes']*60,$id]);});
 }
 public static function expire(PDO $db):int {$count=0;foreach(Db::query($db,"SELECT o.*,d.user_id FROM orders o JOIN store_order_details d ON d.order_id=o.id WHERE o.status='pending' AND d.expires_at<?",[time()])->fetchAll() as $o)Db::transaction($db,function()use($db,$o,&$count){$r=Db::query($db,'SELECT * FROM orders WHERE id=?'.StoreAccess::lock($db),[$o['id']])->fetch();if($r['status']!=='pending')return;self::release($db,$r,['id'=>$o['user_id']]);Db::query($db,"UPDATE orders SET status='expired' WHERE id=?",[$o['id']]);Db::query($db,"UPDATE payments SET status='expired' WHERE order_id=?",[$o['id']]);Db::query($db,"UPDATE store_payment_attempts SET status='expired' WHERE order_id=? AND status='pending'",[$o['id']]);$count++;});return $count;}
}
